mapper.select:
SELECT timeline_seq, timeline_type_cd, title, content_preview, event_dt, use_yn, updated_at, updated_by, created_at, created_by FROM ( SELECT T.TIMELINE_SEQ AS timeline_seq, T.TIMELINE_TYPE_CD AS timeline_type_cd, T.TITLE AS title, DBMS_LOB.SUBSTR(T.CONTENT, 200, 1) AS content_preview, TO_CHAR(T.EVENT_DT, 'YYYY-MM-DD') AS event_dt, NVL(T.USE_YN, 'Y') AS use_yn, TO_CHAR(T.UPDATED_AT, 'YYYY-MM-DD HH24:MI:SS') AS updated_at, T.UPDATED_BY AS updated_by, TO_CHAR(T.CREATED_AT, 'YYYY-MM-DD HH24:MI:SS') AS created_at, T.CREATED_BY AS created_by, ROW_NUMBER() OVER (ORDER BY T.EVENT_DT DESC, T.TIMELINE_SEQ DESC) AS rn FROM ADM_TIMELINE_MST T WHERE 1=1
AND NVL(T.USE_YN, 'Y') = #{use_yn}
AND NVL(T.USE_YN, 'Y') = 'Y'
AND T.TIMELINE_TYPE_CD = #{timeline_type_cd}
AND T.TITLE LIKE '%' || #{title} || '%'
AND T.EVENT_DT >= TO_DATE(#{event_dt_from}, 'YYYY-MM-DD')
AND T.EVENT_DT <= TO_DATE(#{event_dt_to}, 'YYYY-MM-DD')
) R WHERE 1=1
AND R.rn > #{offset}
AND R.rn <= (NVL(#{offset}, 0) + #{size})
ORDER BY R.rn

mapper.update:
UPDATE ADM_TIMELINE_MST
   SET USE_YN = 'N',
       UPDATED_AT = SYSTIMESTAMP,
       UPDATED_BY = #{updated_by}
 WHERE TIMELINE_SEQ = #{timeline_seq}
